    /**
     * Tests creating a new Certification.
     *
     * @return    Certification
     */
    public Certification testCreate() throws Throwable {
    Certification entity = null;

    LOGGER.info( "CertificationTest:testCreate()" );
    LOGGER.info( "-- Attempting to create a Certification");

    StringBuilder msg = new StringBuilder( "-- Failed to create a Certification" );

    try {
        entity = service.createCertification( generateNewCommand() );
        assertNotNull( entity, msg.toString() );

        theId = entity.getCertificationId();
        assertNotNull( theId, msg.toString() + " Contains a null primary key" );

        LOGGER.info( "-- Successfully created a Certification with primary key" + theId );
    }
    catch (Exception e)  {
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() + entity );

        throw e;
    }
    return entity;
}

    /**
     * Tests reading a Certification.
     *
     * @return    Certification
     */
    public Certification testRead() throws Throwable {
    LOGGER.info( "CertificationTest:testRead()" );
    LOGGER.info( "-- Reading a previously created Certification" );

    Certification entity = null;
    StringBuilder msg = new StringBuilder( "-- Failed to read Certification with primary key" );
    msg.append( theId );

    try {
        entity = service.getCertification( new CertificationFetchOneSummary(theId) );

        assertNotNull( entity,msg.toString() );

        // for use later
        theId = entity.getCertificationId();

        LOGGER.info( "-- Successfully found Certification " + entity.toString() );
    }
    catch ( Throwable e ) {
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() + " : " + e );

        throw e;
    }

    return( entity );
}

    /**
     * Tests updating a Certification.
     *
     * @return    Certification
     */
    public Certification testUpdate() throws Throwable {
    LOGGER.info( "CertificationTest:testUpdate()" );
    LOGGER.info( "-- Attempting to update a Certification." );

    StringBuilder msg = new StringBuilder( "Failed to update a Certification : " );
    Certification entity = null;

    try {
        UpdateCertificationCommand updateCommand = this.generateUpdateCommand();

        // apply the current id as to update the fields of the current entity
        updateCommand.setCertificationId( theId );

        assertNotNull( updateCommand, msg.toString() );

        LOGGER.info( "-- Now updating the created Certification." );

        entity = service.updateCertification( updateCommand );

        assertNotNull( entity, msg.toString()  );

        LOGGER.info( "-- Successfully saved Certification - " + entity.toString() );
    }
    catch ( Throwable e ) {
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() + " : primarykey-" + theId + " : entity-" +  entity + " : " + e );

        throw e;
    }

    return( entity );
}

    /**
     * Tests deleting a Certification.
     */
    public void testDelete() throws Throwable {
    LOGGER.info( "CertificationTest:testDelete()" );
    LOGGER.info( "-- Deleting a previously created Certification." );

    try {
        DeleteCertificationCommand deleteCommand = new DeleteCertificationCommand( theId );

        service.delete( deleteCommand );

        LOGGER.info( "-- Successfully deleted Certification with primary key " + theId );
    }
    catch ( Throwable e ) {
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( "-- Failed to delete Certification with primary key " + theId );

        throw e;
    }
}

    /**
     * Tests getting all Certifications.
     *
     * @return    Collection
     */
    public List<Certification> testGetAll() throws Throwable {
    LOGGER.info( "CertificationTest:testGetAll() - Retrieving Collection of Certifications:" );

    StringBuilder msg = new StringBuilder( "-- Failed to get all Certification : " );
    List<Certification> collection  = null;

    try {
        // call the static get method on the CertificationService
        collection = service.getAllCertification();

        if ( collection == null || collection.size() == 0 ) {
            LOGGER.warning( unexpectedErrorMsg );
            LOGGER.warning( "-- " + msg.toString() + " Empty collection returned."  );
        }
        else {
            // Now print out the values
            Certification currEntity  = null;
            Iterator<Certification> iter = collection.iterator();

            while( iter.hasNext() ) {
                // Retrieve the entity
                currEntity = iter.next();

                assertNotNull( currEntity,"-- null value object in Collection." );
                assertNotNull( currEntity.getCertificationId(), "-- value object in Collection has a null primary key" );

                LOGGER.info( " - " + currEntity.toString() );
            }
        }
    }
    catch ( Throwable e ){
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() );

        throw e;
    }

    return( collection );
}

